-- V1: esquema base de ConcretoLab (generado a partir de las entidades JPA).
-- Usa IF NOT EXISTS para poder aplicarse tambien sobre bases creadas antes con ddl-auto=update.
CREATE TABLE IF NOT EXISTS cuadriculas_proyecto (origenx float not null, origeny float not null, proyecto_id bigint not null, niveles varchar(2000) not null, separacionesx varchar(2000) not null, separacionesy varchar(2000) not null, primary key (proyecto_id));
CREATE TABLE IF NOT EXISTS elementos (altura float not null, ancho float not null, largo float not null, x float not null, y float not null, z float not null, id integer, proyecto_id bigint not null, nombre varchar(255) not null, tipo varchar(255) not null, primary key (id));
CREATE TABLE IF NOT EXISTS ensayos (asentamiento_mm float not null, edad_dias float not null, resistencia_mpa float not null, id integer, mezcla_id bigint, fecha varchar(255), identificacion varchar(255), observaciones varchar(255), primary key (id));
CREATE TABLE IF NOT EXISTS expedientes_estructurales (proyecto_id bigint not null, estado_proyecto varchar(255), estudio_suelos varchar(255), fecha_proyecto varchar(255), justificacion_norma varchar(255), norma varchar(255), observaciones varchar(255), profesional varchar(255), ubicacion varchar(255), uso varchar(255), primary key (proyecto_id));
CREATE TABLE IF NOT EXISTS granulometrias (fondo float not null, masa_inicial float not null, id integer, material_id bigint, mediciones varchar(10000), fecha varchar(255), identificacion varchar(255), primary key (id));
CREATE TABLE IF NOT EXISTS materiales (absorcion float, densidad_relativa float, humedad float, modulo_finura float, peso_unitario_compactado float, tamano_maximo_mm float, id integer, fecha_ensayo varchar(255), nombre varchar(255) not null, observaciones varchar(255), procedencia varchar(255), referencia_ensayo varchar(255), tipo varchar(255) not null, primary key (id));
CREATE TABLE IF NOT EXISTS mezclas (absorcion_fino float not null, absorcion_grueso float not null, agua float not null, cemento float not null, fino_sss float not null, grueso_sss float not null, humedad_fino float not null, humedad_grueso float not null, resistencia float not null, id integer, proyecto_id bigint, material_fino varchar(255), material_grueso varchar(255), nombre varchar(255), observaciones varchar(255), referencia varchar(255), primary key (id));
CREATE TABLE IF NOT EXISTS proyectos (id integer, nombre varchar(120) not null, ubicacion varchar(200), primary key (id));
CREATE TABLE IF NOT EXISTS vinculos_geometricos (columna_id bigint not null, id integer, viga_id bigint not null, primary key (id));
